const input = $input.first().json;
const body = input.body || input;
const harveyResponse = body.harvey_response || '';
const requiredSections = body.required_sections || [];
const outputSchema = body.expected_output_schema || {};

const missingSections = [];
const formatErrors = [];

// Check required sections
const responseLower = harveyResponse.toLowerCase();
for (const section of requiredSections) {
  if (!responseLower.includes(section.toLowerCase())) {
    missingSections.push(section);
  }
}

// Check if response is valid (non-empty, has structure)
if (harveyResponse.trim().length === 0) {
  formatErrors.push('Response is empty');
}

if (harveyResponse.length < 100) {
  formatErrors.push('Response suspiciously short (< 100 chars)');
}

// Check for broken markdown
const openBrackets = (harveyResponse.match(/\[/g) || []).length;
const closeBrackets = (harveyResponse.match(/\]/g) || []).length;
if (Math.abs(openBrackets - closeBrackets) > 5) {
  formatErrors.push('Possible broken markdown: bracket mismatch');
}

// Check output schema keys if provided
const schemaKeys = Object.keys(outputSchema);
for (const key of schemaKeys) {
  if (!responseLower.includes(key.toLowerCase()) && !responseLower.includes(key.replace(/_/g, ' ').toLowerCase())) {
    formatErrors.push(`Expected key "${key}" not found in response`);
  }
}

const valid = missingSections.length === 0 && formatErrors.length === 0;

return [{
  json: {
    valid,
    missing_sections: missingSections,
    format_errors: formatErrors,
    stats: {
      sections_checked: requiredSections.length,
      sections_found: requiredSections.length - missingSections.length,
      response_length: harveyResponse.length
    }
  }
}];
